package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class NamibiaGradeSevenRoundingTest {
 @Test public void normalSupplyUsesAllOfficialUnitsWithinOneMillion(){var limits=GlobalCurriculum.limits("na-nied-primary-2024-v1","el_round",7);assertEquals(1000000,limits.wholeMaximum(-1));assertEquals(0,limits.givenMinimum(-1));assertArrayEquals(new int[]{10,100,1000,10000,100000},limits.roundingUnits());Generator g=new Generator(new Random(303));List<String>recent=new ArrayList<>();Set<Integer>units=new HashSet<>();for(int i=0;i<300;i++){Question q=g.next("el_round",recent,false,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());var v=RoundingRelations.read(q);assertNotNull(v);int number=Integer.parseInt(v.first()),unit=v.unit().intValueExact();assertTrue(number>=0&&number<=1000000);units.add(unit);assertFalse(HelpPlan.forQuestion(q).canTransfer());int answer=(number+unit/2)/unit*unit;assertTrue(new Checker().check(q,List.of(),List.of(""+answer)).correct());}assertEquals(Set.of(10,100,1000,10000,100000),units);}
 @Test public void publicBoundaryAndHalfwayDigitsDetermineRounding(){for(int unit:new int[]{10,100,1000,10000,100000})for(int n:new int[]{0,1,unit/2-1,unit/2,unit/2+1,999999,1000000}){Question q=new Question("el_round",n+"을 "+unit+"의 자리까지 반올림하면?","poison","poison");RoundingRelations.attach(q);int expected=(n+unit/2)/unit*unit;assertTrue(new Checker().check(q,List.of(),List.of(""+expected)).correct());assertEquals(Checker.Status.WRONG_ANSWER,new Checker().check(q,List.of(),List.of(""+(expected+unit))).status);assertFalse(HelpPlan.forQuestion(q).canTransfer());}}
}
